import{_ as t,o as a,c as n,a0 as o}from"./chunks/framework.DzvPB4Y-.js";const u=JSON.parse('{"title":"Sheet Types, Rotation and Spacing","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/bpp2d/business-scenario.md","filePath":"frameworks/bpp2d/business-scenario.md"}'),s={name:"frameworks/bpp2d/business-scenario.md"};function i(r,e,d,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="sheet-types-rotation-and-spacing" tabindex="-1">Sheet Types, Rotation and Spacing <a class="header-anchor" href="#sheet-types-rotation-and-spacing" aria-label="Permalink to &quot;Sheet Types, Rotation and Spacing&quot;">​</a></h1><p>After <a href="./first-layout.html">your first 2D layout</a>, separate geometry, material consumption and cost with four items. Replace the first-lesson items and sheet types with this input.</p><h2 id="_1-two-sheets-and-one-rectangle-type" tabindex="-1">1. Two Sheets and One Rectangle Type <a class="header-anchor" href="#_1-two-sheets-and-one-rectangle-type" aria-label="Permalink to &quot;1. Two Sheets and One Rectangle Type&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Object</th><th>Dimensions / amount</th><th style="text-align:right;">Price</th></tr></thead><tbody><tr><td>R</td><td>2 × 2 m, four pieces</td><td style="text-align:right;">—</td></tr><tr><td>S</td><td>4 × 4 m, at least one available</td><td style="text-align:right;">5</td></tr><tr><td>L</td><td>5 × 5 m, at least one available</td><td style="text-align:right;">3</td></tr></tbody></table><p>Use ample weight capacity, no rotation and zero spacing first. Four items fit an exact 2×2 grid on S and also fit on L. Pure area consumption favors S (16 m²); pure purchase cost favors L (3). Minimum sheet count cannot distinguish them.</p><p>Set spacing to 0.2 m: two items need <code>2 + 0.2 + 2 = 4.2 m</code> per row. S loses the 2×2 layout while L remains feasible. Total item area of 16 m² does not establish fit; four axis-aligned 2×2 squares have no alternative four-piece layout with positive gaps on a 4×4 sheet either.</p><h2 id="_2-send-every-sheet-type-to-generation" tabindex="-1">2. Send Every Sheet Type to Generation <a class="header-anchor" href="#_2-send-every-sheet-type-to-generation" aria-label="Permalink to &quot;2. Send Every Sheet Type to Generation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Responsibility</th><th>Kotlin</th><th>Rust</th></tr></thead><tbody><tr><td>Multiple types</td><td><code>Bpp2dLayerGenerationRequest.sheets</code></td><td>Sheet collection on <code>Bpp2dLayerGenerationRequest</code></td></tr><tr><td>Candidate identity</td><td><code>Layer.sheet</code> retains its type</td><td>Each candidate retains its actual sheet type</td></tr><tr><td>Spacing</td><td>Request <code>kerf</code></td><td>Request <code>with_kerf(...)</code></td></tr><tr><td>Objective</td><td>Area, count and per-type cost pipelines</td><td>Corresponding area, count and type-cost pipelines</td></tr></tbody></table><p>The primary/default <code>sheet</code> does not replace the full <code>sheets</code> collection. Identical coordinates on S and L are different columns: do not deduplicate by coordinates alone.</p><p>Use the first-lesson item constructors, create S and L sheet types and pass both into the request. Wire cost into the master objective rather than only adding prices to an output table.</p><h2 id="_3-check-the-spacing-path-separately" tabindex="-1">3. Check the Spacing Path Separately <a class="header-anchor" href="#_3-check-the-spacing-path-separately" aria-label="Permalink to &quot;3. Check the Spacing Path Separately&quot;">​</a></h2><p>After changing spacing, regenerate candidates, solve again and independently measure actual edge-to-edge gaps. Fewer candidates do not prove every placement has legal spacing.</p><h2 id="_4-isolate-rotation-in-another-tiny-case" tabindex="-1">4. Isolate Rotation in Another Tiny Case <a class="header-anchor" href="#_4-isolate-rotation-in-another-tiny-case" aria-label="Permalink to &quot;4. Isolate Rotation in Another Tiny Case&quot;">​</a></h2><p>Use one <code>3 × 2 m</code> sheet and one <code>2 × 3 m</code> rectangle with zero spacing. It fits with 90° rotation and does not fit without rotation. This isolates <code>allowRotate</code>; a square cannot demonstrate the difference.</p><h2 id="_5-business-acceptance" tabindex="-1">5. Business Acceptance <a class="header-anchor" href="#_5-business-acceptance" aria-label="Permalink to &quot;5. Business Acceptance&quot;">​</a></h2><ul><li>At zero spacing, a pure area objective favors S and pure cost favors L. With weighted objectives, recompute the configured score instead of retaining both single-objective expectations.</li><li>Regenerate, solve and validate after a spacing change; moving coordinates in a picture does not enforce a rule.</li><li>Stock/procurement limits require real master-model constraints. A catalog of sheet types is not modeled stock.</li><li>Report net item area, consumed sheet area, free regions and reusable remnants separately. Reuse needs business rules such as minimum width/height.</li></ul><p>Continue to <a href="./../csp2d/business-scenario.html">CSP2D process requirements</a> for a guillotine tree, not a renamed BPP2D layout. Complete the <a href="./../integration.html">integration checks</a> before delivering business results.</p><p>Repository regression commands live in <a href="./../verification.html">Verification</a>. Complete the business input, call and result checks before using them.</p>',18)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
